    content: '余禁所禁垣西，是法厅事也，有古槐数株焉。虽生意可知，同殷仲文之古树；而听讼斯在，即周召伯之甘棠。每至夕照低阴，秋蝉疏引，发声幽息，有切尝闻。岂人心异于曩时，将虫响悲于前听。嗟乎！声以动容，德以象贤。故洁其身也，禀君子达人之高行；蜕其皮也，有仙都羽化之灵姿。候时而来，顺阴阳之数；应节为变，审藏用之机。有目斯开，不以道昏而昧其视；有翼自薄，不以俗厚而易其真。吟乔树之微风，韵姿天纵；饮高秋之坠露，清畏人知。仆失路艰虞，遭时徽纆。不哀伤而自怨，未摇落而先衰。闻蟪蛄之流声，悟平反之已奏；见螳螂之抱影，怯危机之未安。感而缀诗，贻诸知己。庶情沿物应，哀弱羽之飘零；道寄人知，悯余声之寂寞。非谓文墨，取代幽忧云尔。\n西陆蝉声唱，南冠客思深。不堪玄鬓影，来对白头吟。露重飞难进，风多响易沉。无人信高洁，谁为表予心。',
    appreciation: '此诗为骆宾王任侍御史时因上疏论事触忤武后，遭诬下狱后所作。借蝉自喻，抒发了品行高洁却遭诬陷的悲愤，是初唐咏物诗的杰作。',
    inspiration: '诗前长序与正文互为表里，序中详述蝉之品格。诗中以蝉自况，露重风多喻政治环境险恶，末句"谁为表予心"的诘问悲愤至极，物我浑然一体。',
    tags: ['初唐', '咏物', '蝉', '悲愤', '五言律诗'],
    category: 'poem',
    fameLevel: 2
